import React, { Component } from 'react';
import classes from './Tutorial.module.css';

class Tutorial extends Component {

    render() {

        let message = (

            <React.Fragment>
                <div>
                    <h3 > Tutorial: </h3>

                    <div className={classes.area}> <p> A) First step: </p> </div>
                    <div className={classes.FirstStep}>
                        <div className={classes.forceFlex}>
                            <p> 1. Download the Metamask extension for your browser </p>
                            <span style={{color: "red"}}> : </span>  
                            <a href="https://metamask.io/"> Download Metamask </a>        
                        </div>
                        <p> 2. Create a Metamask account. </p>
                    </div>
                </div>
            </React.Fragment>
        )

        return (
            <div className={classes.Tutorial}>
               {message} 
            </div>
        )}
    }

export default Tutorial;
